namespace ks{class PanelPublishTask final{public:enum class Stage{HoldSource,HoldOutput,LocateSource,SetLatch,SetCount,ReadShadow,WriteData,WriteLatch,ClearStrobe,HoldDelay,SetDelay,Tick,RepeatDelay,RestoreDelay,SetStrobe,NextLatch,NextSlot,RepeatSlots,RestoreOutput,RestoreSource,Finish,Complete};enum class Read{Shadow,Port};enum class Write{Data,Port,Strobe};Stage stage()const{return stage_;}unsigned index()const{return index_;}uint8_t data()const{return data_;}uint8_t latch()const{return uint8_t(0x30+index_);}uint8_t strobe()const{return strobe_;}unsigned remaining()const{return remaining_;}unsigned delay()const{return delay_;}template<class Clock>unsigned nextClocks(Clock&&clock)const{switch(stage_){case Stage::HoldSource:case Stage::HoldOutput:case Stage::RestoreSource:case Stage::RestoreOutput:return 20;case Stage::LocateSource:return 9;case Stage::SetCount:case Stage::SetDelay:return 6;case Stage::ReadShadow:return 8;case Stage::WriteData:return 3+clock(Write::Data);case Stage::WriteLatch:return 3+clock(Write::Port);case Stage::ClearStrobe:case Stage::SetStrobe:return 8;case Stage::HoldDelay:case Stage::RestoreDelay:return 11;case Stage::Finish:return 17;case Stage::Complete:return 0;default:return 3;}}
template<class Reader,class Writer,class Clock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,Clock&&clock){unsigned used=0;while(auto cost=nextClocks(clock)){if(cost>available-used)break;switch(stage_){case Stage::HoldSource:stage_=Stage::HoldOutput;break;case Stage::HoldOutput:stage_=Stage::LocateSource;break;case Stage::LocateSource:stage_=Stage::SetLatch;break;case Stage::SetLatch:stage_=Stage::SetCount;break;case Stage::SetCount:remaining_=7;stage_=Stage::ReadShadow;break;case Stage::ReadShadow:data_=uint8_t(read(Read::Shadow));stage_=Stage::WriteData;break;case Stage::WriteData:write(Write::Data,data_);stage_=Stage::WriteLatch;break;case Stage::WriteLatch:write(Write::Port,latch());stage_=Stage::ClearStrobe;break;case Stage::ClearStrobe:strobe_=uint8_t(read(Read::Port))&0xdf;write(Write::Strobe,strobe_);stage_=Stage::HoldDelay;break;case Stage::HoldDelay:stage_=Stage::SetDelay;break;case Stage::SetDelay:delay_=3;stage_=Stage::Tick;break;case Stage::Tick:--delay_;stage_=Stage::RepeatDelay;break;case Stage::RepeatDelay:stage_=delay_?Stage::Tick:Stage::RestoreDelay;break;case Stage::RestoreDelay:stage_=Stage::SetStrobe;break;case Stage::SetStrobe:strobe_=uint8_t(read(Read::Port))|0x20;write(Write::Strobe,strobe_);stage_=Stage::NextLatch;break;case Stage::NextLatch:++index_;stage_=Stage::NextSlot;break;case Stage::NextSlot:--remaining_;stage_=Stage::RepeatSlots;break;case Stage::RepeatSlots:stage_=remaining_?Stage::ReadShadow:Stage::RestoreOutput;break;case Stage::RestoreOutput:stage_=Stage::RestoreSource;break;case Stage::RestoreSource:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Stage stage_=Stage::HoldSource;unsigned index_=0,remaining_=0,delay_=0;uint8_t data_=0,strobe_=0;};}
